`src/envs/dev/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

// ── Application logs bucket ──────────────────────────────────────────────────

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

// ── Service-account identity for logs ────────────────────────────────────────
// Account-based programmatic access, same trust as the assets reader.

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

// ── Application logs bucket ──────────────────────────────────────────────────

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

// ── Service-account identity for logs ────────────────────────────────────────
// OIDC-trusted role with Pod Identity, same trust topology as the assets reader.

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
});
```

Both new files follow the existing pattern:
- **Dev**: Account-scoped trust with programmatic access (IAM user) for long-lived credentials
- **Prod**: OIDC-scoped trust with Pod Identity binding for workload authentication
- Each reader grants `s3:GetObject` + `s3:GetObjectVersion` (baseline) + `s3:PutObject` (enumerated via `additionalActions`), scoped precisely to its respective logs bucket
- `SecureBucket` pins versioning, encryption, and public-access blocking unconditionally per the composites' design; no SPEC deviations
- Discovery picks up both files automatically when `chant build src/envs/{dev,prod}/infra` runs
